import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import { useNavigate } from "react-router-dom";
import API_BASE_URL from "../config";
import "../styles/UserPages.css";

const BrowseRentals = () => {
  const [rentals, setRentals] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/rentals`)
      .then((res) => res.json())
      .then((data) => setRentals(data));
  }, []);

  return (
    <>
  <Navbar />
  <div className="page-container">
    <div className="page-header">
      <h2>Browse Available Rentals</h2>
      <div>
        <button className="primary-btn" onClick={() => navigate("/dashboard")}>← Back to Dashboard</button>
      </div>
    </div>

    <div className="card-grid">
      {rentals.length === 0 ? (
        <p>No rentals available.</p>
      ) : (
        rentals.map((rental) => (
          <div className="card" key={rental.id}>
            {rental.image && <img src={rental.image} alt="Rental" className="card-image" />}
            <h4>{rental.title}</h4>
            <p>{rental.description}</p>
            <p><strong>${rental.price}</strong> / {rental.duration}</p>
            <button className="primary-btn" onClick={() => navigate(`/rental-checkout/${rental.id}`)}>Rent Now</button>
          </div>
        ))
      )}
    </div>
  </div>
  <Footer />
</>

  );
};

export default BrowseRentals;
